// UpdateNewValues updates the mutable fields using the new values that were set on create except the ID field.
// Using this option is equivalent to using:
//
//	client.Paper.Create().
//		OnConflict(
//			sql.ResolveWithNewValues(),
//			sql.ResolveWith(func(u *sql.UpdateSet) {
//				u.SetIgnore(paper.FieldID)
//			}),
//		).
//		Exec(ctx)
func (u *PaperUpsertOne) UpdateNewValues() *PaperUpsertOne {
	u.create.conflict = append(u.create.conflict, sql.ResolveWithNewValues())
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(s *sql.UpdateSet) {
		if _, exists := u.create.mutation.ID(); exists {
			s.SetIgnore(paper.FieldID)
		}
		if _, exists := u.create.mutation.CreatedAt(); exists {
			s.SetIgnore(paper.FieldCreatedAt)
		}
		if _, exists := u.create.mutation.AcademicSessionID(); exists {
			s.SetIgnore(paper.FieldAcademicSessionID)
		}
		if _, exists := u.create.mutation.GenerationRunID(); exists {
			s.SetIgnore(paper.FieldGenerationRunID)
		}
		if _, exists := u.create.mutation.PaperCode(); exists {
			s.SetIgnore(paper.FieldPaperCode)
		}
		if _, exists := u.create.mutation.Version(); exists {
			s.SetIgnore(paper.FieldVersion)
		}
	}))
	return u
}

